#!/usr/bin/env python3
# Some portions generated by Codex. Corrected consumer population only.
import pathlib,json
p=pathlib.Path(__file__).resolve().parent;s=json.loads((p/'summary.json').read_text());ids=json.loads((p/'source-identities.json').read_text())
a=['# Narrow six-slot component isolation with a linear benchmark consumer','','## Scope and interpretation','','This is a separate corrected-consumer population. Original narrow-consumer and corrected wide-consumer evidence remain unchanged and separate. Do not pool these samples with the old client or infer a controlled parser speedup from different runs. No production application code changed in this phase. Actual Workbench browser code already used a linear fragment splitter; the repeated scan was in the Node benchmark endpoint only.','','Real on-disk LMDB, synthetic RDF fixture, actual RDF4J Server binary output, Workbench Java decoding/NDJSON serialization and a Node streaming consumer. Not browser rendering, concurrent QPS, cold disk, remote network or server-only throughput.','','## Immutable arms','']
for k,v in ids.items():a.append(f'- {k}: `{v}`')
a+=['','Same pinned binary writer/compact identity mapping/memo/IR stack and 100,000-row six-slot query across arms. Only the read-depth and three-class typed serializer overlays differ. No ordered adapter, resource-holder, initializer restoration, cancellation or test-seam overlays. All 3,137 runtime files reverified against the frozen manifest.','','## Qualification and fixed protocol','','997 differential parser cases passed: byte partitions, multilingual and emoji UTF8, empty/multiple/CRLF lines, malformed JSON/error records, invalid/truncated UTF8 and terminal/EOF rules. Parsed values and error classes match the old consumer; error-message identity is not claimed. Source-level newline-search regions are bounded linearly in the long partial-line test. Lazy line emission preserves the first parsed rows-batch boundary. Four full-term HTTP qualifications passed independent every-term/unique-bag checks and dual checksums, expected route/origins and no spill/migration.','','One fixed four-block Latin square, four fresh JVMs per arm, 60 warmups and 20 measured queries each: 1,280 clean-protocol requests, 320 measured. All observations retained; no adaptive extension or tail selection. Profiles use separate JVMs and are never pooled into clean timings. First-batch latency is after JSON.parse of the first complete rows record, normally 32 rows, not first engine tuple or browser paint. EOF includes Node decoding/counting/backpressure.','','## Clean means','','| Arm | EOF ms | First batch ms | Derived rows/s | Fork EOF range ms |','|---|---:|---:|---:|---:|']
for k,v in s['arms'].items():
 m=v['means'];a.append(f"| {k} | {m['eofMs']:.3f} | {m['firstRowMs']:.3f} | {100000000/m['eofMs']:.0f} | {v['forkRangeEofMs'][0]:.3f}–{v['forkRangeEofMs'][1]:.3f} |")
a+=['','Derived rows/s is reciprocal sequential full-response latency, not concurrent serving capacity. Positive reductions below mean lower latency.','','## Component contrasts']
for metric in ['eofMs','firstRowMs']:
 a+=['',f'### {metric}','','| Contrast | Reduction % | Four paired reductions % | Descriptive 95% interval % |','|---|---:|---|---|']
 for k,v in s['contrasts'].items():
  q=v[metric];a.append(f"| {k} | {q['latencyReductionPercent']:.3f} | {', '.join(f'{x:+.2f}' for x in q['pairedReductionPercent'])} | {q['descriptive95ReductionInterval'][0]:+.2f} to {q['descriptive95ReductionInterval'][1]:+.2f} |")
a+=['','Intervals use four independent paired log fork means and t with three degrees of freedom, unadjusted for multiple comparisons. Within-fork requests are not independent replications. A crossing-zero interval does not establish equivalence.']
for k,v in s['interaction'].items():a.append(f"- {k} interaction ratio {v['geometricInteractionRatio']:.4f}, interval {v['descriptive95RatioInterval'][0]:.4f}–{v['descriptive95RatioInterval'][1]:.4f}.")
a+=['','## All forks','','| Fork | EOF ms | First batch ms |','|---|---:|---:|']
for f in s['forks']:a.append(f"| {f['name']} | {f['means']['eofMs']:.3f} | {f['means']['firstRowMs']:.3f} |")
a+=['','## Convergence','','| Arm | First measured third ms | Middle third ms | Last third ms |','|---|---:|---:|---:|']
for k,v in s['arms'].items():a.append('| '+k+' | '+' | '.join(f'{x:.3f}' for x in v['measuredThirdMeanEofMs'])+' |')
a+=['','Fixed longer warmup does not automatically prove convergence. Every measured index remains included. Whole-JVM GC logs include startup/warmup and cannot be assigned to particular query times; heap snapshots are not allocation or retained-heap measurements. Narrow results remain separate evidence. Prior application safety tests are scoped, not a whole-repository pass or automatic merge readiness.','','## Framing and observed route counters','']
for k in ['rowRecords','firstRecordRows','firstRecordBytes','contentEncoding','bytes']:
 a.append(f"- {k}: "+'; '.join(arm+' '+str(sorted({v for f in s['forks'] if f['arm']==arm for v in f['framing'][k]})) for arm in ids))
for k in ['LmdbNativeJaninoCodegen:COMPILATIONS','LmdbNativeJaninoCodegen:CACHE_HITS','NativeDistinctTracker:PRIMITIVE_ROWS','NativeExpressionDomain:SPILL_FILES_CREATED','NativeBudgetedWideDistinct:MIGRATED']:
 a.append(f"- {k}: "+'; '.join(arm+' '+str(sorted({v for f in s['forks'] if f['arm']==arm for v in f['counterDeltas'].get(k,[])})) for arm in ids))
a+=['','These counters establish observed routing/cache/grouping, not byte-identical generated plans or JIT machine code. Bytes are decoded stream bytes, not compressed wire bytes.','','## Evidence','','summary.json retains every request index, fork, contrast, counter and framing observation. Exact protocol/source/runtime manifests and raw logs remain available; evidence/index.json plus pool chunks reconstruct textual run artifacts with verified SHA-256. Large JFR/Node raw files remain local with hashes; compact profile summaries are separate.']
(p/'RESULTS.md').write_text('\n'.join(a)+'\n')
